package workspaces

import (
	"context"
	"log"
	"runtime"
	"strings"
	"sync"
	"time"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/credentials"
	"github.com/anthnel/devdesk/internal/git"
	"github.com/anthnel/devdesk/internal/gitlab"
	"github.com/anthnel/devdesk/internal/scan"
)

// clearFooterInfoCmd returns a command that clears the footer info message after a delay.
func clearFooterInfoCmd() tea.Cmd {
	return tea.Tick(3*time.Second, func(time.Time) tea.Msg {
		return clearFooterInfoMsg{}
	})
}

// clearSyncSummaryCmd drops a finished sync's summary from the footer after the
// same three seconds every other footer message gets (Rule 128).
func clearSyncSummaryCmd() tea.Cmd {
	return tea.Tick(3*time.Second, func(time.Time) tea.Msg {
		return clearSyncSummaryMsg{}
	})
}

// syncSpec is what a batch of syncs needs from the model, copied out before the
// first command runs (Rule 110).
type syncSpec struct {
	gitlabURL string
	// token loads the configured GitLab token, at most once for the batch. It
	// is a closure rather than the token itself so the keyring read happens on
	// a command's goroutine — Update does no I/O — and so twelve repositories
	// do not produce twelve reads.
	token func() string
	jobs  int
}

// tokenLoader returns a function that loads the GitLab token once and then
// answers from memory. A missing token is not an error: a public repository
// fetches without one, and a private one fails with git's own reason.
func tokenLoader(storage credentials.Storage, gitlabURL string) func() string {
	if storage == nil || gitlabURL == "" {
		return func() string { return "" }
	}
	var once sync.Once
	var token string
	return func() string {
		once.Do(func() {
			loaded, err := gitlab.NewAuth(storage).LoadCredentials(gitlabURL)
			if err != nil {
				log.Printf("ERROR [workspaces] loading the sync token: %v", err)
				return
			}
			token = loaded
		})
		return token
	}
}

// syncOneRepoCmd syncs a single repository, bounded by the batch's semaphore.
func syncOneRepoCmd(repoPath string, spec syncSpec, sem chan struct{}) tea.Cmd {
	return tea.Sequence(
		func() tea.Msg { return WorkspaceSyncStartingMsg{RepoPath: repoPath} },
		func() tea.Msg {
			sem <- struct{}{}
			defer func() { <-sem }()

			msg := WorkspaceSyncCompleteMsg{RepoPath: repoPath}
			remote, err := git.RemoteURL(repoPath)
			if err != nil {
				msg.Error = err
				return msg
			}

			result, err := git.Sync(repoPath, git.SyncOptions{
				Token: tokenForRemote(remote, spec.gitlabURL, spec.token),
			})
			msg.Error = err
			msg.Outcome = result.Outcome
			msg.Behind = result.Behind
			msg.Reason = result.Reason

			// Re-read the repository whatever happened. A refused sync fetched
			// all the same, so its counts are current now even though nothing
			// merged — which is the answer to D35 and the reason a refusal is
			// still worth something.
			msg.Status = readGitStatus(repoPath)
			return msg
		},
	)
}

// batchSyncCmd syncs every path through a pool of gitlab.pull.parallel_jobs.
//
// The setting is shared with the explorer's clone deliberately: both are "how
// many git network operations at once", and one number the user can reason
// about beats two they have to keep in step.
func batchSyncCmd(repoPaths []string, spec syncSpec) tea.Cmd {
	sem := make(chan struct{}, max(spec.jobs, 1))
	cmds := make([]tea.Cmd, len(repoPaths))
	for i, path := range repoPaths {
		cmds[i] = syncOneRepoCmd(path, spec, sem)
	}
	return tea.Batch(cmds...)
}

// readGitStatus re-reads one repository's git metadata.
func readGitStatus(repoPath string) Entry {
	entry := Entry{Path: repoPath, IsDir: true}
	detectGitStatus(&entry)
	return entry
}

// loadScanCacheCmd loads the workspace scan cache from disk asynchronously
func loadScanCacheCmd() tea.Cmd {
	return func() tea.Msg {
		c, err := cache.NewWorkspaceScanCache(config.CurrentContextName())
		if err != nil {
			return ScanCacheLoadedMsg{Cache: nil}
		}
		return ScanCacheLoadedMsg{Cache: c.GetAll()}
	}
}

// deleteScanCacheCmd removes the given repo paths from the disk cache (Rule 126: scan all purges cache)
func deleteScanCacheCmd(paths []string) tea.Cmd {
	return func() tea.Msg {
		c, err := cache.NewWorkspaceScanCache(config.CurrentContextName())
		if err != nil {
			return nil
		}
		for _, path := range paths {
			_ = c.Delete(path)
		}
		return nil
	}
}

// scanOneRepoCmd scans a single git repo directory, using a semaphore to limit concurrency.
// It emits WorkspaceScanStartingMsg before scanning and WorkspaceScanCompleteMsg after.
func scanOneRepoCmd(repoPath string, opts scan.ScanOptions, sem chan struct{}) tea.Cmd {
	return tea.Sequence(
		func() tea.Msg {
			return WorkspaceScanStartingMsg{RepoPath: repoPath}
		},
		func() tea.Msg {
			sem <- struct{}{}
			defer func() { <-sem }()

			scanner := scan.NewScanner(opts)
			result, err := scanner.Scan(context.Background(), repoPath, scan.TargetDirectory)
			if err != nil {
				log.Printf("ERROR [workspaces] scan %s: %v", repoPath, err)
				return WorkspaceScanCompleteMsg{
					RepoPath: repoPath,
					Error:    err,
				}
			}

			if len(result.Errors) > 0 && result.TotalFindings() == 0 {
				combined := strings.Join(result.Errors, "; ")
				log.Printf("ERROR [workspaces] scan errors for %s: %s", repoPath, combined)
			}

			// Le verdict vient du scan et de nulle part ailleurs : la boucle
			// « une finding dont Source vaut gitleaks » qui était ici ne voyait
			// pas les secrets trouvés par Trivy, et ne savait pas dire qu'aucune
			// étape n'avait cherché.
			sensitive := result.SecretVerdict()

			entry := cache.WorkspaceScanEntry{
				RepoPath:  repoPath,
				Critical:  result.Counts.Critical,
				High:      result.Counts.High,
				Medium:    result.Counts.Medium,
				Low:       result.Counts.Low,
				Sensitive: sensitive,
				ScannedAt: result.EndTime,
			}

			wc, cErr := cache.NewWorkspaceScanCache(config.CurrentContextName())
			if cErr != nil {
				log.Printf("ERROR [workspaces] open cache: %v", cErr)
			} else if sErr := wc.Set(repoPath, entry); sErr != nil {
				log.Printf("ERROR [workspaces] cache set %s: %v", repoPath, sErr)
			}

			if sErr := cache.SaveWorkspaceScanResult(repoPath, result); sErr != nil {
				log.Printf("ERROR [workspaces] save full result %s: %v", repoPath, sErr)
			}

			return WorkspaceScanCompleteMsg{
				RepoPath:  repoPath,
				Critical:  entry.Critical,
				High:      entry.High,
				Medium:    entry.Medium,
				Low:       entry.Low,
				Sensitive: sensitive,
				ScannedAt: entry.ScannedAt,
			}
		},
	)
}

// batchScanCmd scans all provided repo paths in parallel using a worker pool
// of runtime.NumCPU()/2 workers (minimum 1).
func batchScanCmd(repoPaths []string, opts scan.ScanOptions) tea.Cmd {
	numWorkers := runtime.NumCPU() / 2
	if numWorkers < 1 {
		numWorkers = 1
	}
	sem := make(chan struct{}, numWorkers)

	cmds := make([]tea.Cmd, len(repoPaths))
	for i, path := range repoPaths {
		cmds[i] = scanOneRepoCmd(path, opts, sem)
	}
	return tea.Batch(cmds...)
}

package workspaces

import (
	"fmt"
	"os"
	"path/filepath"

	"github.com/charmbracelet/bubbles/spinner"
	tea "github.com/charmbracelet/bubbletea"

	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
)

// Init initialise le modèle
func (m Model) Init() tea.Cmd {
	return tea.Batch(m.loadEntries(), loadScanCacheCmd(), m.spinner.Tick)
}

// InEditMode returns true if the view is in an edit mode (input, confirm, selection, or filter search)
func (m Model) InEditMode() bool {
	return m.mode != ModeNormal || m.table.InEditMode()
}

// FilterBarVisible returns true when the filter bar is visible (implements app.FilterBarView).
func (m Model) FilterBarVisible() bool {
	return m.table.FilterBar().IsVisible() && m.mode == ModeNormal && len(m.table.Items()) > 0 && m.error == ""
}

// Update gère les messages
func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	var cmd tea.Cmd

	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.updateTableSize()

	case tea.KeyMsg:
		return m.handleKeyMsg(msg)

	case EntriesLoadedMsg:
		m.setEntries(msg.Entries)
		m.error = ""
		m.refreshRows()
		if m.pendingCursor >= 0 {
			m.table.SetCursor(m.pendingCursor)
			m.pendingCursor = -1
		}

	case LoadErrorMsg:
		m.error = msg.Error.Error()

	case WorkspaceInputSubmitMsg:
		return m.handleInputSubmit(msg)

	case RenameInputSubmitMsg:
		return m.handleRenameSubmit(msg)

	case WorkspaceInputCancelMsg:
		m.mode = ModeNormal
		m.input = nil
		return m, nil

	case WorkspaceCreatedMsg:
		return m.handleWorkspaceCreated(msg)

	case EntryDeletedMsg:
		return m.handleEntryDeleted(msg)

	case EntryRenamedMsg:
		return m.handleEntryRenamed(msg)

	case sharedcomponents.ConfirmModalYesMsg:
		return m.handleConfirmDelete()

	case sharedcomponents.ConfirmModalNoMsg:
		m.mode = ModeNormal
		m.confirmModal = nil
		return m, nil

	case TerminalExitMsg:
		return m, m.loadEntries()

	case TerminalOpenedMsg:
		return m.handleTerminalOpened(msg)

	case IDEOpenedMsg:
		if msg.Error != nil {
			m.error = msg.Error.Error()
		}
		return m, nil

	case BrowserOpenedMsg:
		if msg.Error != nil {
			m.error = msg.Error.Error()
		}
		return m, nil

	case spinner.TickMsg:
		if len(m.scanningPaths) > 0 || len(m.syncingPaths) > 0 {
			var cmd tea.Cmd
			m.spinner, cmd = m.spinner.Update(msg)
			m.spinnerFrameIdx = (m.spinnerFrameIdx + 1) % len(spinner.Dot.Frames)
			m.refreshRows()
			return m, cmd
		}

	case ScanCacheLoadedMsg:
		if msg.Cache != nil {
			m.scanCache = msg.Cache
			m.refreshRows()
		}
		return m, nil

	case ScanRequestMsg:
		return m.handleScanRequest(msg)

	case WorkspaceScanStartingMsg:
		tick := m.spinnerTickIfIdle()
		m.scanningPaths[msg.RepoPath] = true
		m.footerInfo = ""
		m.refreshRows()
		return m, tick

	case WorkspaceScanCompleteMsg:
		return m.handleWorkspaceScanComplete(msg)

	case WorkspaceSyncStartingMsg:
		tick := m.spinnerTickIfIdle()
		m.syncingPaths[msg.RepoPath] = true
		m.footerInfo = ""
		m.refreshRows()
		return m, tick

	case WorkspaceSyncCompleteMsg:
		return m.handleWorkspaceSyncComplete(msg)

	case clearSyncSummaryMsg:
		// Only a settled run is dropped: a second sync started inside the three
		// seconds must not have its progress wiped by the first one's timer.
		if m.sync != nil && m.sync.finished() {
			m.sync = nil
		}
		return m, nil

	case clearFooterInfoMsg:
		m.footerInfo = ""
		m.footerError = ""
	}

	// Update table only in normal mode
	if m.mode == ModeNormal {
		cmd = m.table.Update(msg)
	}

	return m, cmd
}

// handleKeyMsg handles keyboard input
func (m Model) handleKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	// Filter bar search mode - delegate to filter bar
	if m.table.InEditMode() {
		return m, m.table.Update(msg)
	}

	// Mode input - delegate to input component
	if m.mode == ModeAdding && m.input != nil {
		var cmd tea.Cmd
		m.input, cmd = m.input.Update(msg)
		return m, cmd
	}

	// Mode confirm - delegate to confirm modal
	if m.mode == ModeConfirmingDelete && m.confirmModal != nil {
		var cmd tea.Cmd
		m.confirmModal, cmd = m.confirmModal.Update(msg)
		return m, cmd
	}

	// Mode renaming - delegate to input component
	if m.mode == ModeRenaming && m.input != nil {
		var cmd tea.Cmd
		m.input, cmd = m.input.Update(msg)
		return m, cmd
	}

	// Selection mode - pick a directory for security view
	if m.mode == ModeSelecting {
		return m.handleSelectionKeyMsg(msg)
	}

	// Normal mode
	switch msg.String() {
	case "/":
		return m, m.table.Update(msg)
	case "enter":
		return m.openScanDetails()
	case "ctrl+r":
		return m, m.loadEntries()
	case "ctrl+n":
		return m.startAdd()
	case "r":
		return m.startRename()
	case "ctrl+d":
		return m.startDelete()
	case "t":
		return m.openTerminalInPlace(m.resolveTargetPath())
	case "T":
		return m.openTerminalWindow()
	case "ctrl+o":
		return m.openIDE()
	case "ctrl+w":
		return m.openInBrowser()
	case "ctrl+s":
		return m.startSecurityScan()
	case "s":
		return m.startSync()
	case "A":
		return m.scanAllUnscanned()
	case "ctrl+a":
		return m.requestScanAll()
	case "left", "h":
		return m.navigateUp()
	case "right", "l":
		return m.navigateIn()
	case "esc":
		return m.navigateUp()
	case "up", "down", "k", "j", "pgup", "pgdown", "g", "home", "G", "end":
		return m, m.table.Update(msg)
	}

	return m, nil
}

// spinnerTickIfIdle restarts the spinner chain when nothing was keeping it
// alive, and is why both Starting handlers read it *before* recording their
// path.
//
// The TickMsg handler stops scheduling the next tick once nothing is running —
// there is no reason to rebuild the rows sixty times a second for a settled
// table — so the chain Init started dies on its first tick. Nothing brought it
// back, and a scan's spinner has therefore been frozen on frame zero since it
// was written: it looked like a marker rather than an animation, so it never
// read as broken. Starting a second chain alongside a live one is the opposite
// mistake, and makes the frames advance at twice the rate.
//
// One window is left, and deliberately: an action started before Init's first
// tick has arrived doubles the chain until the view is closed. It is the
// spinner's own frame interval wide, and the cost is a spinner that spins fast.
func (m Model) spinnerTickIfIdle() tea.Cmd {
	if len(m.scanningPaths) > 0 || len(m.syncingPaths) > 0 {
		return nil
	}
	return m.spinner.Tick
}

// tabCount returns the total number of tabs (home + navigation stack entries + current)
func (m Model) tabCount() int {
	count := 1 // home tab
	count += len(m.navigationStack)
	if m.currentPath != "" {
		count++ // current directory tab
	}
	return count
}

// navigateIn enters the selected directory
func (m Model) navigateIn() (tea.Model, tea.Cmd) {
	entry, ok := m.selectedEntry()
	if !ok || !entry.IsDir {
		return m, nil
	}

	// Save cursor position before navigating down
	m.cursorStack = append(m.cursorStack, m.table.Cursor())
	// Push current path onto navigation stack
	if m.currentPath != "" {
		m.navigationStack = append(m.navigationStack, m.currentPath)
	}
	m.currentPath = entry.Path
	m.activeTabIndex = m.tabCount() - 1
	m.pendingCursor = -1
	return m, m.loadEntries()
}

// navigateUp goes to the parent directory
func (m Model) navigateUp() (tea.Model, tea.Cmd) {
	if m.currentPath == "" {
		return m, nil
	}

	if len(m.navigationStack) > 0 {
		// Pop from stack
		m.currentPath = m.navigationStack[len(m.navigationStack)-1]
		m.navigationStack = m.navigationStack[:len(m.navigationStack)-1]
	} else {
		// Go back to root
		m.currentPath = ""
	}

	// Restore cursor position at the parent level after entries load
	if len(m.cursorStack) > 0 {
		m.pendingCursor = m.cursorStack[len(m.cursorStack)-1]
		m.cursorStack = m.cursorStack[:len(m.cursorStack)-1]
	} else {
		m.pendingCursor = -1
	}

	m.activeTabIndex = m.tabCount() - 1
	return m, m.loadEntries()
}

// handleSelectionKeyMsg handles keyboard input in selection mode
func (m Model) handleSelectionKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "esc":
		if m.currentPath != "" {
			return m.navigateUp()
		}
		return m, func() tea.Msg { return SelectionCancelledMsg{} }
	case "enter":
		// Confirm selection: use the current browsing directory (not the highlighted entry).
		// Use → / l to navigate into a subdirectory first.
		path := m.currentPath
		if path == "" {
			path = m.getExpandedWorkspacesDir()
		}
		return m, func() tea.Msg { return DirectorySelectedMsg{Path: path} }
	case "left", "h":
		return m.navigateUp()
	case "right", "l":
		return m.navigateIn()
	case "up", "down", "k", "j", "pgup", "pgdown", "g", "home", "G", "end":
		return m, m.table.Update(msg)
	}
	return m, nil
}

// getExpandedWorkspacesDir returns the workspaces directory with tilde expanded
func (m Model) getExpandedWorkspacesDir() string {
	workspacesDir := m.config.App.WorkspacesDir
	if len(workspacesDir) >= 2 && workspacesDir[:2] == "~/" {
		home, _ := os.UserHomeDir()
		workspacesDir = filepath.Join(home, workspacesDir[2:])
	}
	return workspacesDir
}

// startAdd switches to input mode for creating a new workspace/folder
func (m Model) startAdd() (tea.Model, tea.Cmd) {
	m.mode = ModeAdding
	m.input = NewWorkspaceInput()
	return m, nil
}

// startDelete switches to confirm mode for deleting an entry
func (m Model) startDelete() (tea.Model, tea.Cmd) {
	entry, ok := m.selectedEntry()
	if !ok {
		return m, nil
	}

	m.pendingEntry = &entry
	m.mode = ModeConfirmingDelete

	var title string
	if entry.IsDir {
		title = "Delete Directory"
	} else {
		title = "Delete File"
	}

	m.confirmModal = sharedcomponents.NewConfirmModal(
		title,
		fmt.Sprintf("Are you sure you want to delete '%s'?\n\nThis will permanently delete it and all its contents.", entry.Name),
	)
	return m, nil
}

// startRename switches to rename mode for the selected entry
func (m Model) startRename() (tea.Model, tea.Cmd) {
	entry, ok := m.selectedEntry()
	if !ok {
		return m, nil
	}
	m.pendingEntry = &entry
	m.mode = ModeRenaming
	m.input = NewRenameInput(entry.Name)
	return m, nil
}

// handleRenameSubmit handles the rename form submission
func (m Model) handleRenameSubmit(msg RenameInputSubmitMsg) (tea.Model, tea.Cmd) {
	m.mode = ModeNormal
	m.input = nil
	if m.pendingEntry == nil {
		return m, nil
	}
	return m, m.renameEntry(m.pendingEntry.Path, msg.Name)
}

// renameEntry renames a filesystem entry
func (m Model) renameEntry(oldPath, newName string) tea.Cmd {
	newPath := filepath.Join(filepath.Dir(oldPath), newName)
	return func() tea.Msg {
		if err := os.Rename(oldPath, newPath); err != nil {
			return EntryRenamedMsg{Error: err}
		}
		return EntryRenamedMsg{OldPath: oldPath, NewPath: newPath}
	}
}

// handleEntryRenamed handles the result of entry renaming
func (m Model) handleEntryRenamed(msg EntryRenamedMsg) (tea.Model, tea.Cmd) {
	if msg.Error != nil {
		m.error = msg.Error.Error()
		return m, nil
	}
	return m, m.loadEntries()
}

// handleInputSubmit handles the workspace input form submission
func (m Model) handleInputSubmit(msg WorkspaceInputSubmitMsg) (tea.Model, tea.Cmd) {
	m.mode = ModeNormal
	m.input = nil
	return m, m.createWorkspace(msg.Name)
}

// handleConfirmDelete handles the confirmation of entry deletion
func (m Model) handleConfirmDelete() (tea.Model, tea.Cmd) {
	m.mode = ModeNormal
	m.confirmModal = nil

	if m.pendingEntry == nil {
		return m, nil
	}
	return m, m.deleteEntry(m.pendingEntry.Path)
}

// handleWorkspaceCreated handles the result of workspace creation
func (m Model) handleWorkspaceCreated(msg WorkspaceCreatedMsg) (tea.Model, tea.Cmd) {
	if msg.Error != nil {
		m.error = msg.Error.Error()
		return m, nil
	}
	return m, m.loadEntries()
}

// handleEntryDeleted handles the result of entry deletion
func (m Model) handleEntryDeleted(msg EntryDeletedMsg) (tea.Model, tea.Cmd) {
	if msg.Error != nil {
		m.error = msg.Error.Error()
		return m, nil
	}
	return m, m.loadEntries()
}

