402			_, hasScanResult = m.scanCache[selectedEntry.Path]
403		}
404		hasSubRepos := selectedEntry != nil && !isGitRepo && len(selectedEntry.SubRepoPaths) > 0
405	
406		shortcuts := []shortcut.Shortcut{
407			{Key: "←→", Description: "Open/Back"},
408		}
409	
410		// enter: only shown for git repos with cached scan results
411		if hasScanResult {
412			shortcuts = append(shortcuts, shortcut.Shortcut{Key: "enter", Description: "Scan details"})
413		}
414	
415		shortcuts = append(shortcuts,
416			shortcut.Shortcut{Key: "t", Description: "Terminal (in-place)"},
417			shortcut.Shortcut{Key: "T", Description: "Terminal (new window)"},
