package app

import (
	"strings"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/ui/theme"
)

// View rend l'interface : header, ligne de titre, viewport, footer (Rule 124).
// Un overlay ouvert remplace le tout.
func (a *App) View() string {
	if overlay := a.activeOverlay(); overlay != "" {
		return lipgloss.Place(a.width, a.height, lipgloss.Center, lipgloss.Center, overlay,
			lipgloss.WithWhitespaceBackground(theme.ColorBackground))
	}

	inner := a.renderHeader() + "\n" + a.renderTitleLine() + "\n" + a.renderBody()
	if footer := a.renderViewFooter(); footer != "" {
		inner += "\n" + footer
	}

	return lipgloss.Place(a.width, a.height, lipgloss.Left, lipgloss.Top, inner,
		lipgloss.WithWhitespaceBackground(theme.ColorBackground))
}

// activeOverlay returns the overlay to draw instead of the view, or "" when
// there is none. The order matches the one handleKeyMsg dispatches in, so the
// overlay holding the keyboard is the one on screen.
func (a *App) activeOverlay() string {
	switch {
	case a.showHelp:
		return a.renderHelpOverlay()
	case a.showContextList:
		return a.renderContextListOverlay()
	}
	return ""
}

// renderBody fills the viewport with the active view's content, padded to the
// full inner width so no line shows the terminal's own background (Rule 115).
func (a *App) renderBody() string {
	content := "View not found: " + string(a.currentView)
	if view, ok := a.views[a.currentView]; ok {
		content = view.View()
	}

	innerWidth := a.viewport.Width - 2 // -2 pour les bordures
	if a.frameless() {
		innerWidth = a.viewport.Width
	}
	a.viewport.SetContent(lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Foreground(theme.ColorText).
		Width(innerWidth).
		Render(content))

	body := a.viewport.View()

	// Rule 136: with a filter bar below it, the viewport's bottom corners become
	// T-junctions so the two form one closed rectangle.
	if view, ok := a.views[a.currentView]; ok {
		if fbv, ok := view.(FilterBarView); ok && fbv.FilterBarVisible() {
			body = replaceViewportBottomCorners(body)
		}
	}
	return body
}

// renderTitleLine draws the viewport's top border carrying the view's title —
// or, for a frameless view, a titled rule with no corners: GetTitle() garde un
// lecteur là où une bordure haute dessinerait le haut d'une boîte inexistante.
func (a *App) renderTitleLine() string {
	title := ""
	if view, ok := a.views[a.currentView]; ok {
		if hv, implements := view.(HeaderView); implements {
			title = hv.GetTitle()
		}
	}
	if a.frameless() {
		return theme.RenderTitledRule(title, a.width)
	}
	return theme.RenderBorderTitle(title, a.width)
}

// frameless reports whether the active view draws its own frames (see
// FramelessView). Le défaut est encadré.
func (a *App) frameless() bool {
	view, ok := a.views[a.currentView]
	if !ok {
		return false
	}
	fv, implements := view.(FramelessView)
	return implements && fv.Frameless()
}

// renderViewFooter returns the active view's footer, or "" when it has none.
func (a *App) renderViewFooter() string {
	if view, ok := a.views[a.currentView]; ok {
		if fv, ok := view.(FooterView); ok {
			return fv.RenderFooter(a.width)
		}
	}
	return ""
}

// replaceViewportBottomCorners turns the viewport's bottom └ and ┘ into the
// T-junctions ├ and ┤, so the filter bar rendered below it in the footer joins
// the border into one closed rectangle instead of two stacked boxes.
func replaceViewportBottomCorners(body string) string {
	lastNewline := strings.LastIndex(body, "\n")
	if lastNewline == -1 {
		return body
	}
	lastLine := body[lastNewline+1:]
	lastLine = strings.Replace(lastLine, "└", "├", 1)
	lastLine = strings.Replace(lastLine, "┘", "┤", 1)
	return body[:lastNewline+1] + lastLine
}

package app

import (
	"log"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/command"
	ociresources "github.com/anthnel/devdesk/internal/ui/oci_resources"
	"github.com/anthnel/devdesk/internal/ui/security"
	"github.com/anthnel/devdesk/internal/ui/workspaces"
)

// Rule 126: opening a scanned item reads the cache; it never triggers a scan.
// The full result lives in its own file, so the metadata entry can outlive it —
// every load here has a fallback for that.

// handleWorkspaceScanDetails loads a cached workspace scan result from disk.
func (a *App) handleWorkspaceScanDetails(msg workspaces.ScanDetailsRequestMsg) (tea.Model, tea.Cmd) {
	repoPath := msg.RepoPath
	return a, func() tea.Msg {
		result, err := cache.LoadWorkspaceScanResult(repoPath)
		return WorkspaceScanResultLoadedMsg{Result: result, RepoPath: repoPath, Err: err}
	}
}

// handleScanDetailsRequest loads a cached image scan result from disk.
func (a *App) handleScanDetailsRequest(msg ociresources.ScanDetailsRequestMsg) (tea.Model, tea.Cmd) {
	log.Printf("Scan details requested for image: %s", msg.ImageName)
	imageName := msg.ImageName
	return a, func() tea.Msg {
		result, err := cache.LoadImageScanResult(imageName)
		return ImageScanResultLoadedMsg{Result: result, ImageName: imageName, Err: err}
	}
}

// A missing result file is not a dead end, and it is not the security view's
// problem either: the list the user pressed enter in is where the target lives
// and where the scan that would replace it runs. So the fallback stays put and
// asks that list to rescan, rather than opening a security view on nothing.
//
// It used to open the scan form with the target filled in. With the form gone
// there is nothing to fill in — every option comes from the configuration view
// — so what is left to carry is the target's name.

// handleWorkspaceScanResultLoaded opens the security view on the loaded result,
// or asks the workspaces list to rescan the repository.
func (a *App) handleWorkspaceScanResultLoaded(msg WorkspaceScanResultLoadedMsg) (tea.Model, tea.Cmd) {
	if msg.Err != nil || msg.Result == nil {
		log.Printf("Workspace scan result not on disk for %s (rescanning): %v", msg.RepoPath, msg.Err)
		return a.rescanInOrigin(command.ViewWorkspaces, workspaces.ScanRequestMsg{TargetPath: msg.RepoPath})
	}
	return a, a.openSecurityView(
		security.NewWithPreloadedResult(a.config, msg.Result),
		command.ViewWorkspaces,
	)
}

// handleImageScanResultLoaded opens the security view on the loaded result, or
// asks the images list to rescan the image.
func (a *App) handleImageScanResultLoaded(msg ImageScanResultLoadedMsg) (tea.Model, tea.Cmd) {
	if msg.Err != nil || msg.Result == nil {
		log.Printf("Image scan result not on disk for %s (rescanning): %v", msg.ImageName, msg.Err)
		return a.rescanInOrigin(command.ViewOCIResources, ociresources.ScanRequestMsg{ImageName: msg.ImageName})
	}
	return a, a.openSecurityView(
		security.NewWithPreloadedResult(a.config, msg.Result),
		command.ViewOCIResources,
	)
}

// rescanInOrigin hands a scan request to the list the target belongs to, and
// stays there. The view is created if it is not open — the request can arrive
// from a cached row whose list was dropped on a context switch.
func (a *App) rescanInOrigin(view command.ViewType, request tea.Msg) (tea.Model, tea.Cmd) {
	a.createView(view)
	held, ok := a.views[view]
	if !ok {
		return a, nil
	}
	a.currentView = view
	updatedView, cmd := held.Update(request)
	a.views[view] = updatedView
	return a, tea.Batch(cmd, a.requestResize())
}

// openSecurityView installs a freshly built security view, records where esc
// should return to, and lays it out.
func (a *App) openSecurityView(view security.Model, origin command.ViewType) tea.Cmd {
	view.OriginView = origin
	a.views[command.ViewSecurity] = view
	a.currentView = command.ViewSecurity
	return tea.Batch(view.Init(), a.requestResize())
}

// routeToSecurityView forwards a message to the security view even when it is
// not on screen, for the same reason as routeToOCIImagesView below: a scan
// started there has to finish there.
func (a *App) routeToSecurityView(msg tea.Msg) (tea.Model, tea.Cmd) {
	view, ok := a.views[command.ViewSecurity]
	if !ok {
		return a, nil
	}
	updatedView, cmd := view.Update(msg)
	a.views[command.ViewSecurity] = updatedView
	return a, cmd
}

// routeToOCIImagesView forwards a message to the OCI view even when it is not
// on screen, so a scan started there keeps progressing while the user is
// elsewhere.
func (a *App) routeToOCIImagesView(msg tea.Msg) (tea.Model, tea.Cmd) {
	view, ok := a.views[command.ViewOCIResources]
	if !ok {
		return a, nil
	}
	updatedView, cmd := view.Update(msg)
	a.views[command.ViewOCIResources] = updatedView
	return a, cmd
}

// handleLaunchScan is gone with the form. It carried the options the form had
// collected back to the view that would run the scan; the options come from the
// configuration view now, so there is nothing to carry — rescanInOrigin names a
// target and that is all.

