// it, by dropping it so it is rebuilt normally.
//
// Only the workspaces view is lent now. The images view was the other one — the
// security form borrowed it to pick a scan target — and it could not simply be
// dropped, because it holds scan results worth keeping; it took a
// ResetSelectionMsg instead. That whole path went with the form (phase 3).
func (a *App) resetSelectionModeFor(view command.ViewType) {
	if view == command.ViewWorkspaces {
		delete(a.views, view)
	}
}

// switchView change la vue courante
func (a *App) switchView(view command.ViewType) tea.Cmd {
	// Lazy loading des vues
	if _, exists := a.views[view]; !exists {
		a.createView(view)
	}

	a.currentView = view

	newView, ok := a.views[view]
	if !ok {
		return nil
	}
	log.Printf("Switching to view: %s, calling Init()", view)

	// Init() + un WindowSizeMsg pour forcer le redimensionnement
	return tea.Batch(newView.Init(), a.requestResize())
}

// createView crée une vue (lazy loading)
func (a *App) createView(view command.ViewType) {
	if _, exists := a.views[view]; exists && view != command.ViewGitlabAuth {
		return
	}

	switch view {
	case command.ViewDashboard:
		a.views[view] = dashboard.New(a.config, a.sharedState)
	case command.ViewStatus:
		a.views[view] = status.New(a.config)
	case command.ViewGitlabAuth:
		a.views[view] = a.newAuthView()
	case command.ViewGitlabExplorer:
		a.views[view] = explorer.New(a.config, a.sharedState)
	case command.ViewWorkspaces:
		a.views[view] = workspaces.New(a.config, a.sharedState.Secrets.Storage)
	case command.ViewSecurity:
		a.views[view] = security.New(a.config)
	case command.ViewContainers:
		a.views[view] = containers.New(a.config)
	case command.ViewOCIResources:
		a.views[view] = ociresources.New(a.config)
	case command.ViewNetdiag:
		a.views[view] = netdiag.New(a.config)
	case command.ViewConfiguration:
		a.views[view] = configuration.New(a.config)
	}
}

// newAuthView builds the GitLab auth view against this context's credentials.
// It is rebuilt on every switch rather than cached, so the form reflects the
// session that is current now.
func (a *App) newAuthView() tea.Model {
	log.Printf("Creating GitLab auth view with context: %s", a.currentContext)

	authView := auth.New(a.config, a.sharedState.Secrets, a.sharedState.SecretNotices)
	if a.sharedState.GitLabClient != nil && a.sharedState.CurrentUser != nil {
		authView.SetAuth(a.sharedState.GitLabClient, a.sharedState.CurrentUser)
	}
	return authView
}

// updateCompletions met à jour les suggestions basées sur l'input actuel
func (a *App) updateCompletions() {
	input := a.commandInput.Value()

	// Reset index si input change
	if input != a.completionInput {
		a.completionIndex = 0
		a.completionInput = input
	}

	a.completionSuggestions = a.completionEngine.GetSuggestions(input)
}

// handleCompletionCycle cycle à travers les suggestions (Tab répété)
func (a *App) handleCompletionCycle() (tea.Model, tea.Cmd) {
	if len(a.completionSuggestions) == 0 {
		return a, nil
	}

	// Increment avec wrap-around
	a.completionIndex = (a.completionIndex + 1) % len(a.completionSuggestions)
	return a, nil
}

// resetCompletion nettoie l'état de complétion
func (a *App) resetCompletion() {
	a.completionSuggestions = nil
	a.completionIndex = 0
	a.completionInput = ""
}

package app

import (
	"fmt"
	"strings"

	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
	"github.com/charmbracelet/lipgloss"
)

// HeaderView est l'interface que chaque vue doit implémenter pour fournir les données du header
type HeaderView interface {
	GetShortcuts() shortcut.Shortcuts
	GetTitle() string
	GetIcon() string
	GetHeaderInfo(context string) []shortcut.HeaderInfo
}

// FooterView is implemented by views that have footer content rendered below the viewport border (Rule 124).
// The footer can contain a tab bar (1 line) and optionally an empty line + info line (2 lines).
type FooterView interface {
	GetFooterHeight() int          // current footer height in lines (0 if no footer)
	RenderFooter(width int) string // rendered footer content
}

// FramelessView is implemented by a view that draws its own frames and wants
// none around it. Le défaut — encadré — est le comportement sûr : une vue qui
// n'implémente pas ça est encadrée comme toutes les autres, contrairement à
// HeaderView dont la moitié manquante rend un titre vide en silence.
//
// Une seule vue l'implémente (le dashboard), et c'est délibéré : toutes les
// autres encadrent un objet unique — une table, un formulaire.
type FramelessView interface {
	Frameless() bool
}

// headerMinHeight est la hauteur fixe du header (sans la ligne de commande).
const headerMinHeight = 7

// ASCII logo for the header
var logoLines = []string{
	`    ____            ____            __  `,
	`   / __ \___ _   __/ __ \___  _____/ /__`,
	`  / / / / _ \ | / / / / / _ \/ ___/ //_/`,
	` / /_/ /  __/ |/ / /_/ /  __(__  ) ,<   `,
	`/_____/\___/|___/_____/\___/____/_/|_|  `,
}

const logoWidth = 40 // max width of a logo line

package app

import (
	"strings"
	"testing"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/ui/help"
)

// The router probes each view for optional interfaces and silently falls back
// when one is missing. That is the right behaviour and a bad failure mode: the
// configuration view implemented GetShortcuts and GetTitle but not GetIcon or
// GetHeaderInfo, so it satisfied none of HeaderView and the viewport rendered
// an empty title — with nothing to say so.
//
// Checking every view the command parser can name turns that into a build-time
// contract rather than something noticed by looking at the screen.
func TestEveryViewSuppliesItsHeaderAndHelp(t *testing.T) {
	for _, name := range command.ViewNames() {
		view := command.ViewType(name)

		t.Run(name, func(t *testing.T) {
			app := newWithSize(testConfig(), 120, 40)
			app.createView(view)

			built, ok := app.views[view]
			if !ok {
				t.Fatalf("createView(%q) built nothing; the switch has no case for it", view)
			}

			hv, ok := built.(HeaderView)
			if !ok {
				t.Fatalf("%q does not implement HeaderView, so the router renders an empty title for it", view)
			}
			if strings.TrimSpace(hv.GetTitle()) == "" {
				t.Errorf("%q has an empty title", view)
			}
			if len(hv.GetShortcuts()) == 0 {
				t.Errorf("%q advertises no shortcuts", view)
			}

			if _, ok := built.(help.Provider); !ok {
				t.Errorf("%q does not implement help.Provider, so ? shows nothing (Rule 114)", view)
			}
		})
	}
}

// Le cadre du viewport appartient au routeur, et une vue qui s'en passe doit
// dessiner les siens. Une seule le fait — le dashboard, qui est la seule vue à
// ne pas encadrer un objet unique. Ce test tient l'exception à une exception.
func TestOnlyTheDashboardIsFrameless(t *testing.T) {
	for _, name := range command.ViewNames() {
		view := command.ViewType(name)

		app := newWithSize(testConfig(), 120, 40)
		app.createView(view)
		app.currentView = view

		frameless := app.frameless()
		if want := name == "dashboard"; frameless != want {
			t.Errorf("%q reports frameless=%v, want %v", view, frameless, want)
		}
	}
}

// Une vue dont la hauteur de footer dépend de sa propre taille — le dashboard
// cache sa barre d'onglets quand il n'en reste qu'un — ne peut pas répondre
// juste à la première question du routeur, qui arrive avant qu'elle connaisse
// sa nouvelle taille. resize() itère pour ça, et ce test l'épingle : sans la
// seconde passe, le viewport reste décalé d'une ligne jusqu'au resize suivant.
func TestResizeConvergesOnAFooterThatDependsOnTheSize(t *testing.T) {
	app := newWithSize(testConfig(), 120, 40)
	app.createView(command.ViewType("dashboard"))
	app.currentView = command.ViewType("dashboard")

	// Small enough for a tab bar, then large enough that there is one tab left.
	app.resize(120, 40)
	small := app.lastFooterHeight

	app.resize(240, 60)
	large := app.lastFooterHeight

	if small != 3 {
		t.Errorf("footer height at 120x40 = %d, want 3 (tab bar + blank + info)", small)
	}
	if large != 2 {
		t.Errorf("footer height at 240x60 = %d, want 2 — the tab bar is gone at wide", large)
	}
	if got := lipgloss.Height(app.renderViewFooter()); got != large {
		t.Errorf("the footer renders %d lines while the layout budgeted %d", got, large)
	}
}

// A frameless view gets the line the bottom border used to cost, and its title
// is a rule rather than the top of a box that is not there.
func TestAFramelessViewGetsTheBorderLineBack(t *testing.T) {
	app := newWithSize(testConfig(), 120, 40)

	app.createView(command.ViewType("dashboard"))
	app.currentView = command.ViewType("dashboard")
	app.resize(120, 40)
	frameless := app.viewport.Height

	app.createView(command.ViewType("status"))
	app.currentView = command.ViewType("status")
	app.resize(120, 40)
	framed := app.viewport.Height

	if frameless <= framed-2 {
		t.Errorf("the frameless viewport is %d lines against %d framed — it did not get the border back",
			frameless, framed)
	}
	if strings.Contains(app.renderTitleLine(), "┌") {
		t.Log("the framed view keeps its corner, as it should")
	}

	app.currentView = command.ViewType("dashboard")
	if title := app.renderTitleLine(); strings.Contains(title, "┌") || strings.Contains(title, "┐") {
		t.Errorf("the frameless title line still draws box corners: %q", title)
	}
}

