	before := len(m.tree.Items())
	m = feed(t, m, testutil.Key("right"), testutil.Key("left"))

	if got := len(m.tree.Items()); got != before {
		t.Errorf("%d rows after expanding a leaf, want %d", got, before)
	}
}

